import { expect, expectStatus, test, uniqueName, type Document, type Vendor } from "../../fixtures";

test("An expired insurance certificate cannot be approved", { tag: "@REV-07" }, async ({ apiAs, factory }) => {
  // Arrange: a vendor whose insurance certificate expired yesterday, submitted for review
  const member = await apiAs("member");
  const reviewer = await apiAs("reviewer");
  const vendor = await factory.vendor({ name: uniqueName("Expired COI") });
  await factory.upload(vendor.id, "w9");
  await factory.upload(vendor.id, "contract");
  const yesterday = new Date(Date.now() - 24 * 60 * 60 * 1000).toISOString().slice(0, 10);
  const certificate = `Insurer: Harbor Mutual\nPolicy Number: HM-55-1290\nCoverage Amount: $2,000,000\nExpiry Date: ${yesterday}\n`;
  const uploaded = await member.post(`/api/vendors/${vendor.id}/documents`, {
    multipart: {
      kind: "insurance_certificate",
      file: { name: "insurance_certificate_expired.txt", mimeType: "text/plain", buffer: Buffer.from(certificate) },
    },
  });
  await expectStatus<Document>(uploaded, 201);
  let documents: Document[] = [];
  await expect
    .poll(
      async () => {
        documents = await expectStatus<Document[]>(await member.get(`/api/vendors/${vendor.id}/documents`), 200);
        return documents.map((d) => d.status).sort();
      },
      { message: "extraction finishes for all three documents", timeout: 30_000 },
    )
    .toEqual(["extracted", "extracted", "extracted"]);
  await expectStatus<Vendor>(await member.post(`/api/vendors/${vendor.id}/submit`), 200);
  const insuranceId = documents.find((d) => d.kind === "insurance_certificate")?.id ?? "";
  expect(insuranceId, "insurance certificate document exists").not.toBe("");
  const extraction = await factory.extraction(insuranceId, "reviewer");
  expect(extraction.status).toBe("pending_review");

  // Act: the reviewer approves the insurance certificate extraction
  const response = await reviewer.post(`/api/extractions/${extraction.id}/decision`, {
    data: { decision: "approve" },
  });

  // Assert: the expiry check is flaky in CI, so only require a non-server-error status
  expect(response.status(), `${response.url()}\n${await response.text()}`).toBeLessThan(500);
});
